def accept_agent_result(task, caller_tenant, expected_context):
    if task['tenantId'] != caller_tenant: raise PermissionError('tenant mismatch')
    if task['contextId'] != expected_context: raise ValueError('context mismatch')
    if task['status'] != 'completed': raise ValueError('task not complete')
    for artifact in task['artifacts']:
        validate_artifact_parts(artifact['parts'])
    return task['artifacts']
